<template><view class="service-page"><view class="page-heading"><text class="eyebrow">STORAGE OPERATIONS</text><text class="page-title">图片存储管理</text><text class="page-subtitle">先预览候选，再确认清理；引用中的图片始终受到保护。</text></view><text v-if="state.error" class="error">{{ state.error }}</text><text v-if="state.message" class="success">{{ state.message }}</text><text v-if="state.loading" class="muted">正在核验管理权限与清理候选…</text><button v-if="!currentUser" class="primary" @click="login">管理员登录</button><view v-if="state.data" class="surface"><text class="section-title">本地存储 · 回收站保留 {{ state.data.retentionDays }} 天</text><text class="muted">{{ state.data.note }}</text><text class="label">可清理 {{ state.data.candidates.length }} 张 · {{ displayBytes(state.data.candidates.reduce((total,image)=>total+image.bytes,0)) }}</text><view v-for="image in state.data.candidates" :key="image.id" class="record"><text class="body-copy">{{ image.id }}</text><text class="muted">{{ displayBytes(image.bytes) }} · 版本 {{ image.version }}</text></view><text v-if="!state.data.candidates.length" class="muted">暂无符合条件的图片，无需清理。</text><button class="primary spaced" :disabled="busy || !state.data.candidates.length" @click="purge">确认永久清理候选图片</button></view><view class="page-actions"><button v-if="currentUser" class="secondary" :disabled="busy" @click="manager.refresh()">重新预览</button><button class="text-button" @click="home">返回首页</button></view></view></template>
<script setup>
import {usePrivatePage,ask,login,home} from '@/composables/usePrivatePage.js'
import {mediaCleanup,purgeMedia} from '@/api/platform.js'
import {validateCleanup,displayBytes} from '@/utils/platform.mjs'
const {state,manager,currentUser,busy}=usePrivatePage({load:mediaCleanup,validate:validateCleanup})
function purge(){return manager.mutate({confirm:()=>ask('永久删除，无法恢复',`将清理预览中的${state.value.data.candidates.length}张图片。仅处理回收站超过30天且没有引用的文件，请确认已有必要备份。`),write:snapshot=>purgeMedia(snapshot.candidates),validateReceipt:(value,snapshot)=>{if(value?.accepted!==snapshot.candidates.length)throw new Error('清理回执不匹配')},message:'清理请求已提交；未成功移除的文件仍计入空间，可刷新后重试。'})}
</script>
<style scoped src="@/styles/service-pages.css"></style>
<style scoped>.spaced{margin-top:20px}.record{border-top:1px solid #e6edf7;margin-top:15px;padding-top:15px}</style>
